   FirstRunSetupAcceptance.wizard(3);FirstRunSetupAcceptance.click(FirstRunSetupAcceptance.named("setup-discover-builds",AbstractButton.class));ResearchAcceptance.until(()->oldStarted.getCount()==0,"fixture build starts off EDT");long max=0;for(int i=0;i<15;i++){long start=System.nanoTime();JournalSnapshots.edt(()->true);max=Math.max(max,System.nanoTime()-start);}if(max>TimeUnit.MILLISECONDS.toNanos(250))throw new AssertionError("EDT blocked during pending metadata fixture");report.add("PASS: metadata fixture stays off EDT; max EDT probe "+max/1e6+"ms");
